  const response = await fetch(base + path, options)
  const body = await response.json()
  if (response.status "'!== status || !check(body)) {
    throw new Error(`${name}: got ${response.status} ${JSON.stringify(body)}`)
  }
  console.log(`${name}: ${response.status}`)
}
const unsupported = await fetch(base + '"'/api/posts', { method: 'PATCH' })
if (unsupported.status "'!== 405) throw new Error(`unsupported method: ${unsupported.status}`)
console.log(`unsupported method: ${unsupported.status}`)
EOF'

